@extends('layouts.app') @section('content')<h1>Reports</h1><div class="card p-4"><form method="get" class="row g-3"><div class="col-md-4"><label>Company</label><select id="report-company" name="company_id" class="form-select" onchange="filterAccounts()">@foreach($companies as $c)<option value="{{$c->id}}">{{$c->name}}</option>@endforeach</select></div><div class="col-md-4"><label>From</label><input type="date" name="from" class="form-control"></div><div class="col-md-4"><label>To</label><input type="date" name="to" class="form-control"></div><div class="col-md-6"><label>Account (General Ledger)</label><select id="report-account" name="account_id" class="form-select">@foreach($companies as $c)@foreach($c->accounts as $a)<option data-company="{{$c->id}}" value="{{$a->id}}">{{$a->code}} — {{$a->name}}</option>@endforeach @endforeach</select></div><div class="col-12 d-flex gap-2 flex-wrap"><button formaction="{{route('reports.ledger')}}" class="btn btn-primary">General Ledger</button><button formaction="{{route('reports.trial')}}" class="btn btn-primary">Trial Balance</button><button formaction="{{route('reports.profit-loss')}}" class="btn btn-primary">Profit & Loss</button><button formaction="{{route('reports.balance-sheet')}}" class="btn btn-primary">Balance Sheet</button></div></form></div><script>function filterAccounts(){let company=document.querySelector('#report-company').value,select=document.querySelector('#report-account'),first=null;select.querySelectorAll('option').forEach(option=>{option.hidden=option.dataset.company!==company;if(!option.hidden&&!first)first=option});if(first)select.value=first.value}filterAccounts()</script>@endsection
